(function(){const e=async()=>{const t=document.getElementById("github-stats-container");if(!t)return;const n=t.dataset.repo,s=`github-stats-${n}`,r=60*60*1e3,o=(new Date).getTime(),i=e=>e>=1e6?(e/1e6).toFixed(1)+"M":e>=1e3?(e/1e3).toFixed(1)+"K":e,a=(e,t)=>{const n=document.getElementById("github-stars"),s=document.getElementById("github-forks");n&&(n.textContent=i(e)),s&&(s.textContent=i(t))},e=JSON.parse(localStorage.getItem(s));if(e&&o-e.timestamp<r){a(e.stars,e.forks);return}try{const t=await fetch(`https://api.github.com/repos/${n}`);if(!t.ok)return;const e=await t.json();a(e.stargazers_count,e.forks_count),localStorage.setItem(s,JSON.stringify({stars:e.stargazers_count,forks:e.forks_count,timestamp:o}))}catch(e){console.error("GitHub API error",e)}};e()})()